//   vTop = 1 - row/16;    vBot = 1 - (row+1)/16; // three.js v 轴向上（图集顶部 v 大）
//
// 光照数值约定（与 shaders.js 的 aLight 配合）：
//   面向天 ≥ 天光 1.0；面 shade：顶 1.0 / 南北(z±) 0.8 / 东西(x±) 0.6 / 底 0.5
//   AO：经典 0..3 档 → 1.0 / 0.85 / 0.7 / 0.55（顶点三邻块遮挡数）
//   天光：从该格向上扫到世界顶(96)全为非 opaque → 1.0，否则 0.35
//   方块光：该面相邻格若有 light>0 方块（不扩散），取 max(light/15)
//
// r128 API：BufferGeometry / BufferAttribute / Float32BufferAttribute（全程未用 r150+ 名称）。
(function () {
  'use strict';

  var CHUNK = 16, HEIGHT = 96, SEA = 40;
  if (window.MC_WORLD) { CHUNK = window.MC_WORLD.CHUNK || 16; HEIGHT = window.MC_WORLD.HEIGHT || 96; SEA = window.MC_WORLD.SEA || 40; }

