    var e = 1 / 256;
    return {
      u0: col / 16 + e, u1: (col + 1) / 16 - e,
      vTop: 1 - row / 16 - e, vBot: 1 - (row + 1) / 16 + e
    };
  }

  // ---------- 三类队列 ----------
  function Queues() { this.opaque = new Builder(); this.cutout = new Builder(); this.translucent = new Builder(); }

  // 十字植物（花/草丛）：两个对角交叉面片，各画双面（材质 DoubleSide，这里每面只写一份几何）
  function addCross(q, wx, y, wz, def, sky, defLight) {
    var uv = tileUV(texNameFor(def, 'pz'));
    var shade = 1.0, ao = 1.0, l = shade * ao;
    var skyL = sky * l, blkL = defLight * l;
    var a = 0.146, b = 0.854; // 对角线内收一点
    var uvs = [
      [uv.u0, uv.vTop], [uv.u0, uv.vBot], [uv.u1, uv.vTop], [uv.u1, uv.vBot]
    ];
    var lights = [[skyL, blkL, ao], [skyL, blkL, ao], [skyL, blkL, ao], [skyL, blkL, ao]];
    // 面1：x+ → x- 对角
    q.cutout.quad(
      [wx + a, y + 1, wz + a], [wx + a, y, wz + a], [wx + b, y + 1, wz + b], [wx + b, y, wz + b],
      uvs, lights);
    // 面2：x- → x+ 对角
    q.cutout.quad(
      [wx + a, y + 1, wz + b], [wx + a, y, wz + b], [wx + b, y + 1, wz + a], [wx + b, y, wz + a],
      uvs, lights);
  }

  // 常规立方体面
  function addFace(q, world, queue, wx, y, wz, def, faceName, id) {
    var f = FACES_READY[faceName];
    var d = f.dir;
