      vv = c2[4] ? uv.vTop : uv.vBot;
      uvs.push([u, vv]);
    }
    queue.quad(p[0], p[1], p[2], p[3], uvs, lights);
  }

  // ---------- 主入口 ----------
  function buildChunk(world, cx, cz) {
    topCache = Object.create(null); // 每区块重置列缓存

    var q = new Queues();
    var x, y, z, id, def;

    for (x = 0; x < CHUNK; x++) {
      for (z = 0; z < CHUNK; z++) {
        var wx = cx * CHUNK + x, wz = cz * CHUNK + z;
        for (y = 0; y < HEIGHT; y++) {
          id = sample(world, wx, y, wz);
          if (id === 0) continue;
          def = MC_BLOCKS[id];
          if (!def) continue;

