              q.translucent.id = null;
            }
            var sides = ['px', 'nx', 'pz', 'nz'], si, nbs;
            for (si = 0; si < 4; si++) {
              nbs = sample(world, wx + FACES[sides[si]].dir[0], y, wz + FACES[sides[si]].dir[2]);
              if (!isWater(nbs) && !isOpaque(nbs)) {
                q.translucent.id = 11;
                addFace(q, world, q.translucent, wx, y, wz, def, sides[si]);
                q.translucent.id = null;
              }
            }
            continue;
          }

          // 常规方块：六面各自剔除；cutout 方块（树叶/玻璃）进 cutout 队列
          var queue = def.cutout === true ? q.cutout : q.opaque;
          var faces = ['px', 'nx', 'py', 'ny', 'pz', 'nz'], fi;
          for (fi = 0; fi < 6; fi++) {
            addFace(q, world, queue, wx, y, wz, def, faces[fi]);
          }
        }
      }
    }

    return {
      opaque: q.opaque.build(),
      cutout: q.cutout.build(),
      translucent: q.translucent.build()
    };
  }

  window.MC_MESHER = { buildChunk: buildChunk };
