var LIT = op.attributes.aLight.array;
near(LIT[9 * 2], 0.85, 1e-6, '顶点 AO 1 档 = 0.85');
near(LIT[8 * 2], 1.0, 1e-6, '其余顶点天光×shade = 1.0');
// 且顶面触发了对角翻转分支：索引中应出现 (b,b+1,b+3) 形态 → py quad 索引 8,9,11,8,11,10
var IDX = op.index;
assert(IDX[24] === 8 && IDX[25] === 9 && IDX[26] === 11 && IDX[27] === 8 && IDX[28] === 11 && IDX[29] === 10,
  'AO 翻转分支的三角形绕序应为 8,9,11 / 8,11,10');

// 4) 水：translucent 只有 1 个顶面 quad，顶点 y = 40.875 / 40
var wt = geoms.translucent;
assert(wt, 'translucent 几何应存在');
var WP = wt.attributes.position.array;
near(WP.length / 3, 4, 0.1, '水面只有 1 个顶面 quad');
for (i = 0; i < 4; i++) {
  var wy = WP[i * 3 + 1];
  assert(Math.abs(wy - 40.875) < 1e-6 || Math.abs(wy - 40) < 1e-6, '水面顶点 y 应为 40 / 40.875: ' + wy);
}
var wl = wt.attributes.aLight.array;
near(wl[0], 1.0, 1e-6, '露天水面天光 1.0');

// 5) 十字植物：cutout 恰好 2 quads（8 顶点）
var ct = geoms.cutout;
assert(ct, 'cutout 几何应存在');
near(ct.attributes.position.array.length / 3, 8, 0.1, '十字植物 = 2 quads');
var CP = ct.attributes.position.array;
// 两个对角面片端点应落在 (7.146,7.854) 内收对角上
near(CP[0] - 7, 0.146, 1e-6, '植物对角内收 x');

