near(ct.attributes.position.array.length / 3, 8, 0.1, '十字植物 = 2 quads');
var CP = ct.attributes.position.array;
// 两个对角面片端点应落在 (7.146,7.854) 内收对角上
near(CP[0] - 7, 0.146, 1e-6, '植物对角内收 x');

// 6) 通用：索引合法、UV∈[0,1]、boundingSphere
[geoms.opaque, geoms.cutout, geoms.translucent].forEach(function (g, gi) {
