write_file({"content":"// test/mesher.smoke.js — ST-B mesher 冒烟测试（Node 直接运行：node test/mesher.smoke.js）
// 场景：地表 y=40（石头），另置：悬空草块(10,60,10)、其顶面 AO 邻块石头(11,61,11)、
//       水洼(5,40,5)、草丛(7,41,7)。
// 断言：面剔除 / 贴图槽位 / AO 与对角翻转 / 水面压顶 0.875 / 十字植物 / 索引与 UV 合法性
'use strict';
global.window = global;

// ---- mock THREE（mesher 只用这几个 API） ----
var BufferGeometry = function () { this.attributes = {}; };
BufferGeometry.prototype.setAttribute = function (name, attr) { this.attributes[name] = attr; };
BufferGeometry.prototype.setIndex = function (idx) { this.index = idx; };
BufferGeometry.prototype.computeBoundingSphere = function () {
  var p = this.attributes.position.array, i, k;
  var min = [Infinity, Infinity, Infinity], max = [-Infinity, -Infinity, -Infinity];
  for (i = 0; i < p.length; i += 3) for (k = 0; k < 3; k++) {
    if (p[i + k] < min[k]) min[k] = p[i + k];
    if (p[i + k] > max[k]) max[k] = p[i + k];
  }
  var c = [(min[0] + max[0]) / 2, (min[1] + max[1]) / 2, (min[2] + max[2]) / 2], r = 0;
  for (i = 0; i < p.length; i += 3) {
    var d = Math.sqrt(Math.pow(p[i] - c[0], 2) + Math.pow(p[i + 1] - c[1], 2) + Math.pow(p[i + 2] - c[2], 2));
    if (d > r) r = d;
  }
  this.boundingSphere = { center: c, radius: r };
};
global.THREE = {
  BufferGeometry: BufferGeometry,
  Float32BufferAttribute: function (arr, size) { this.array = arr; this.itemSize = size; }
};

// ---- mock 方块表（id 严格按契约：水=11、草丛=25） ----
global.MC_BLOCKS = [null];
global.MC_BLOCKS[1] = { name: '石头', tex: ['stone'], opaque: true };
global.MC_BLOCKS[2] = { name: '草方块', tex: ['grass_top', 'dirt', 'grass_side'], opaque: true };
global.MC_BLOCKS[11] = { name: '水', tex: ['water'], opaque: false, translucent: true };
global.MC_BLOCKS[25] = { name: '草丛', tex: ['tall_grass'], cross: true };
global.MC_ATLAS = { T: { stone: 5, grass_top: 0, dirt: 1, grass_side: 2, water: 7, tall_grass: 9 } };

// ---- mock world：y<41 全石头；overrides 见上 ----
var overrides = { '10,60,10': 2, '11,61,11': 1, '5,40,5': 11, '7,41,7': 25 };
var mockWorld = {
  getBlock: function (x, y, z) {
    if (y < 0 || y >= 96) return 0;
    var o = overrides[x + ',' + y + ',' + z];
    return o !== undefined ? o : (y < 41 ? 1 : 0);
  }
};

require('../js/mesher.js');
var geoms = global.MC_MESHER.buildChunk(mockWorld, 0, 0);

function assert(cond, msg) { if (!cond) { console.error('FAIL: ' + msg); process.exit(1); } }
function near(a, b, eps, msg) { assert(Math.abs(a - b) <= (eps || 1e-4), msg + ' (got ' + a + ', want ' + b + ')'); }

// 把 quad 列表导出：[{v:[[x,y,z]×4], uv:[[u,v]×4], lit:[[sky,blk]×4], idx:[6], base}]
function quads(geo) {
  var out = [];
  if (!geo) return out;
  var I = geo.index, P = geo.attributes.position.array, U = geo.attributes.uv.array, L = geo.attributes.aLight.array;
  for (var j = 0; j < I.length; j += 6) {
    var b = I[j], q = { base: b, v: [], uv: [], lit: [], idx: I.slice(j, j + 6) };
    for (var k = 0; k < 4; k++) {
      q.v.push([P[b * 3 + k * 3], P[b * 3 + k * 3 + 1], P[b * 3 + k * 3 + 2]]);
      q.uv.push([U[b * 2 + k * 2], U[b * 2 + k * 2 + 1]]);
      q.lit.push([L[b * 2 + k * 2], L[b * 2 + k * 2 + 1]]);
    }
    out.push(q);
  }
  return out;
}
// 找 quad：4 顶点全落在一个包围盒内
function findQuad(list, min, max) {
  for (var i = 0; i < list.length; i++) {
    var q = list[i], ok = true;
    for (var k = 0; k < 4 && ok; k++) {
      for (var a = 0; a < 3; a++) {
        if (q.v[k][a] < min[a] - 1e-6 || q.v[k][a] > max[a] + 1e-6) { ok = false; break; }
      }
    }
    if (ok) return q;
  }
  return null;
}

// 1) 队列与 quad 数：272 = 255 地面顶面 + 5 水洼面(4坑壁+1水底石面) + 6 草块 + 6 石块
var op = quads(geoms.opaque);
assert(geoms.opaque, 'opaque 几何应存在');
assert(op.length === 272, 'opaque quads=272 (got ' + op.length + ')');
var ct = quads(geoms.cutout);
assert(ct.length === 2, 'cutout 十字植物 = 2 quads (got ' + ct.length + ')');
var wt = quads(geoms.translucent);
assert(wt.length === 1, 'translucent 水面 = 1 quad (got ' + (wt.length) + ')');

// 2) 草块(10,60,10)六面几何 + 贴图槽位
function faceByPlane(list, axis, val, lo, hi) {
  // 在 list 中找：沿 axis 平面 = val，另两轴范围 [lo,hi]
  for (var i = 0; i < list.length; i++) {
    var q = list[i], flat = true;
    for (var k = 0; k < 4; k++) if (Math.abs(q.v[k][axis] - val) > 1e-6) flat = false;
    if (!flat) continue;
    var ok = true;
    for (k = 0; k < 4 && ok; k++) {
      for (var a = 0; a < 3; a++) {
        if (a === axis) continue;
        if (q.v[k][a] < lo[a] - 1e-6 || q.v[k][a] > hi[a] + 1e-6) { ok = false; break; }
      }
    }
    if (ok) return q;
  }
  return null;
}
var B0 = [10, 60, 10], B1 = [11, 61, 11]; // 草块包围盒 min/max
function faceOf(list, face) {
  // face: 'px'|'nx'|'py'|'ny'|'pz'|'nz' → 平面值 + 另两轴范围
  var map = {
    px: [0, 11, [10, 60, 10], [10, 61, 11]], nx: [0, 10, [10, 60, 10], [10, 61, 11]],
    py: [1, 61, [10, 60, 10], [11, 61, 11]], ny: [1, 60, [10, 60, 10], [11, 61, 11]],
    pz: [2, 11, [10, 60, 10], [11, 61, 11]], nz: [2, 10, [10, 60, 10], [11, 61, 11]]
  };
  var m = map[face];
  return faceByPlane(list, m[0], m[1], m[2], m[3]);
}
['px', 'nx', 'py', 'ny', 'pz', 'nz'].forEach(function (f) {
  assert(faceOf(op, f), '草块 ' + f + ' 面应存在');
});
// py 面所有顶点 y=61、贴图 u∈tile0(grass_top)
var py = faceOf(op, 'py');
py.v.forEach(function (v) { near(v[1], 61, 1e-6, '草块 py 顶点 y'); });
var uMin = Infinity, uMax = -Infinity, vMax = -Infinity;
py.uv.forEach(function (uv) { if (uv[0] < uMin) uMin = uv[0]; if (uv[0] > uMax) uMax = uv[0]; if (uv[1] > vMax) vMax = uv[1]; });
assert(uMax <= 1 / 16 + 1e-6, 'py 用 grass_top(tile0): uMax=' + uMax);
var ny = faceOf(op, 'ny');
var nyU = [Infinity, -Infinity];
ny.uv.forEach(function (uv) { if (uv[0] < nyU[0]) nyU[0] = uv[0]; if (uv[0] > nyU[1]) nyU[1] = uv[0]; });
assert(nyU[0] >= 1 / 16 - 1e-6 && nyU[1] <= 2 / 16 + 1e-6, 'ny 用 dirt(tile1): ' + nyU);
var pz = faceOf(op, 'pz');
var pzU = [Infinity, -Infinity]; var pzVTop = -Infinity;
pz.uv.forEach(function (uv) { if (uv[0] < pzU[0]) pzU[0] = uv[0]; if (uv[0] > pzU[1]) pzU[1] = uv[0]; if (uv[1] > pzVTop) pzVTop = uv[1]; });
assert(pzU[0] >= 2 / 16 - 1e-6 && pzU[1] <= 3 / 16 + 1e-6, '侧面用 grass_side(tile2): ' + pzU);
near(pzVTop, 1 - 1 / 256, 1e-3, '侧面 v 顶≈1（绿边朝上）');

// 3) AO：py 面顶点 (11,61,11) = 0.85（石头斜邻），其余 3 顶点 = 1.0；且触发对角翻转
py.v.forEach(function (v, k) {
  var want = (v[0] === 11 && v[2] === 11) ? 0.85 : 1.0;
