{"content":"// js/shaders.js — ST-B：三种共享 ShaderMaterial（three.js r128）
// 顶点属性：position / uv（three 对 ShaderMaterial 自动声明）+ 自定义 aLight(vec2)
//   aLight.x = 天光 × 面shade × AO（随 uDayBrightness 昼夜缩放）
//   aLight.y = 方块光 × 面shade × AO（荧石等自发光，不随昼夜）
// 片元：光照合成 + 线性雾；cutout 用 discard 镂空；water α=0.75 + 顶点波动。
// UV 约定见 mesher.js 头注释（u0/u1/vTop/vBot）。
(function () {
  'use strict';

  var VERT = [
    'attribute vec2 aLight;',
    'uniform float uTime;',
    'varying vec2 vUv;',
    'varying vec2 vLight;',
    'varying float vFogDepth;',
    'void main() {',
    '  vUv = uv;',
    '  vLight = aLight;',
    '  vec3 pos = position;',
    '  #ifdef WATER_WAVE',
    // 水面波动：相位用世界坐标（modelMatrix 含区块平移），幅度 0.04；
    // fract(position.y) 让满格底边(整数y)固定、水面顶点(0.875)全幅波动。
    '    vec3 wPos = (modelMatrix * vec4(position, 1.0)).xyz;',
    '    float wave = sin(uTime * 2.2 + wPos.x * 0.8 + wPos.z * 1.4) * 0.04;',
    '    pos.y += wave * fract(position.y);',
    '  #endif',
    '  vec4 mv = modelViewMatrix * vec4(pos, 1.0);',
    '  vFogDepth = -mv.z;',
    '  gl_Position = projectionMatrix * mv;',
    '}'
  ].join('\n');

  var FRAG = [
    'uniform sampler2D uMap;',
    'uniform float uDayFactor;',
    'uniform float uDayBrightness;', // = 0.25 + 0.75 * uDayFactor（CPU 侧每帧同步）
    'uniform vec3 uFogColor;',
    'uniform float uFogNear;',
    'uniform float uFogFar;',
    'varying vec2 vUv;',
    'varying vec2 vLight;',
    'varying float vFogDepth;',
    'void main() {',
    '  vec4 tex = texture2D(uMap, vUv);',
    '  #ifdef CUTOUT',
    '  if (tex.a < 0.5) discard;',
    '  #endif',
    '  float l = clamp(max(vLight.x * uDayBrightness, vLight.y), 0.04, 1.0);',
    '  vec3 col = tex.rgb * l;',
    '  float f = clamp((vFogDepth - uFogNear) / max(uFogFar - uFogNear, 0.001), 0.0, 1.0);',
    '  col = mix(col, uFogColor, f);',
    '  #ifdef WATER_WAVE',
    '  gl_FragColor = vec4(col, 0.75);',
    '  #else',
    '  gl_FragColor = vec4(col, 1.0);',
    '  #endif',
    '}'
  ].join('\n');

  function baseUniforms(tex) {
    return {
      uMap: { value: tex || null },
      uDayFactor: { value: 1.0 },
      uDayBrightness: { value: 1.0 },
      uFogColor: { value: new THREE.Color(0x87ceeb) },
      uFogNear: { value: 60.0 },
      uFogFar: { value: 88.0 },
      uTime: { value: 0.0 }
    };
  }

  function build(tex, defines, opts) {
    return new THREE.ShaderMaterial({
      uniforms: baseUniforms(tex),
      vertexShader: VERT,
      fragmentShader: FRAG,
      defines: defines || {},
      side: opts.side,
      transparent: !!opts.transparent,
      depthWrite: opts.depthWrite !== false
    });
  }

  window.MC_SHADERS = {
    // 不透明方块（石头/泥土/原木…）：背面剔除 + 深度写入
    makeOpaqueMaterial: function (tex) {
      return build(tex, {}, { side: THREE.FrontSide, transparent: false });
    },
    // 镂空队列（树叶/玻璃/十字植物）：α<0.5 discard；
    // DoubleSide 保证十字植物、树叶背面对玩家可见（mesher 不复制背面三角形）
    makeCutoutMaterial: function (tex) {
      return build(tex, { CUTOUT: 1 }, { side: THREE.DoubleSide, transparent: false });
    },
    // 水：α=0.75、不写深度、双面、顶点波动
    makeWaterMaterial: function (tex) {
      return build(tex, { WATER_WAVE: 1 }, { side: THREE.DoubleSide, transparent: true, depthWrite: false });
    }
  };
})();
