{"content":"<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>网页版 Minecraft — Wovra 还原</title>
<style>
/* ============ 全局 ============ */
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { width: 100%; height: 100%; overflow: hidden; background: #000; }
body {
  font-family: "Microsoft YaHei", "SimHei", sans-serif;
  user-select: none;
  -webkit-user-select: none;
}
#game-canvas { display: block; width: 100%; height: 100%; image-rendering: pixelated; }

/* ============ 加载屏 ============ */
#loading {
  position: fixed; inset: 0; z-index: 200;
  background-color: #4c4c4c;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
}
#loading-title {
  font-size: 64px; font-weight: 900; letter-spacing: 6px;
  color: #ffffff;
  text-shadow: 4px 4px 0 #3f3f3f;
}
#loading-sub { color: #dedede; margin-top: 10px; font-size: 15px; }
#loading-bar-outer {
  margin-top: 36px; width: 420px; max-width: 80vw; height: 22px;
  border: 3px solid #000; background: #6d6d6d; padding: 2px;
}
#loading-bar-inner {
  height: 100%; width: 0%; background: #7fbf4d;
  transition: width 0.15s linear;
}
#loading-tip { margin-top: 14px; color: #bdbdbd; font-size: 13px; }

/* ============ 十字准星（CSS 绘制，mix-blend-mode:difference） ============ */
#crosshair {
  position: fixed; left: 50%; top: 50%; width: 22px; height: 22px;
  transform: translate(-50%, -50%);
  z-index: 40; pointer-events: none; mix-blend-mode: difference;
  display: none;
}
#crosshair::before, #crosshair::after {
  content: ""; position: absolute; background: #fff;
}
#crosshair::before { left: 50%; top: 0; width: 2px; height: 100%; transform: translateX(-50%); }
#crosshair::after { top: 50%; left: 0; width: 100%; height: 2px; transform: translateY(-50%); }

/* ============ 热栏（ui.js 动态填充 9 格） ============ */
#hotbar {
  position: fixed; bottom: 8px; left: 50%; transform: translateX(-50%);
  display: none; /* 进游戏后由 ui.js 改为 flex */
  z-index: 40;
  background: rgba(0,0,0,0.45);
  border: 3px solid #262626; padding: 3px;
}
.hotbar-slot {
  width: 52px; height: 52px; position: relative;
  border: 2px solid #8b8b8b; background: rgba(30,30,30,0.6);
  margin: 1px; cursor: pointer;
}
.hotbar-slot.selected {
  border: 3px solid #ffffff;
  box-shadow: 0 0 0 1px #000;
  margin: 0;
}
.hotbar-slot canvas { width: 100%; height: 100%; image-rendering: pixelated; }

/* ============ 方块选择器（E 键开关） ============ */
#block-picker {
  position: fixed; left: 50%; top: 50%; transform: translate(-50%, -50%);
  z-index: 60; width: 480px; max-width: 92vw;
  background: rgba(20,20,20,0.85);
  border: 3px solid #262626;
  padding: 14px;
  display: none;
}
#block-picker h3 { color: #fff; font-size: 18px; margin-bottom: 10px; font-weight: 700; }
#picker-grid { display: grid; grid-template-columns: repeat(8, 1fr); gap: 4px; }
.picker-item {
  aspect-ratio: 1 / 1; border: 2px solid #8b8b8b; background: rgba(60,60,60,0.7);
  display: flex; align-items: center; justify-content: center; cursor: pointer;
}
.picker-item:hover { border-color: #fff; background: rgba(120,120,120,0.7); }
.picker-item canvas { width: 100%; height: 100%; image-rendering: pixelated; }

/* ============ 暂停菜单（ESC） ============ */
#pause-menu {
  position: fixed; inset: 0; z-index: 100;
  background: rgba(0,0,0,0.55);
  display: none;
  align-items: center; justify-content: center;
}
.pause-box { width: 340px; max-width: 90vw; text-align: center; }
.pause-box h2 { color: #fff; font-size: 30px; margin-bottom: 24px; text-shadow: 2px 2px 0 #000; }
.mc-btn {
  display: block; width: 100%; padding: 12px 0; margin: 8px 0;
  background: #6f6f6f;
  border: 2px solid #000;
  border-top-color: #a8a8a8; border-left-color: #a8a8a8;
  border-bottom-color: #3d3d3d; border-right-color: #3d3d3d;
  color: #fff; font-size: 17px; cursor: pointer;
  text-shadow: 2px 2px 0 rgba(0,0,0,0.6);
  font-family: inherit;
}
.mc-btn:hover { background: #8a8f8a; color: #ffffa0; }
.mc-btn:active {
  border-top-color: #3d3d3d; border-left-color: #3d3d3d;
  border-bottom-color: #a8a8a8; border-right-color: #a8a8a8;
}
#pause-help {
  color: #ddd; font-size: 14px; line-height: 1.8; text-align: left;
  display: none; margin-top: 14px;
}

/* ============ F3 调试 ============ */
#debug {
  position: fixed; left: 8px; top: 8px; z-index: 45;
  color: #fff; background: rgba(0,0,0,0.35);
  padding: 6px 10px; font-size: 13px; line-height: 1.6;
  white-space: pre; display: none;
}

/* ============ 水下滤镜 ============ */
#underwater-overlay {
  position: fixed; inset: 0; z-index: 30; pointer-events: none;
  background: rgba(20, 60, 130, 0.35);
  display: none;
}

/* ============ 标题栏（左上角小字） ============ */
#title-bar {
  position: fixed; left: 8px; top: 8px; z-index: 40;
  color: rgba(255,255,255,0.8); font-size: 12px;
  text-shadow: 1px 1px 0 rgba(0,0,0,0.8);
  display: none;
}
</style>
</head>
<body>
  <!-- 渲染画布 -->
  <canvas id="game-canvas"></canvas>

  <!-- 十字准星 -->
  <div id="crosshair"></div>

  <!-- 热栏 -->
  <div id="hotbar"></div>

  <!-- 方块选择器 -->
  <div id="block-picker">
    <h3>选择方块</h3>
    <div id="picker-grid"></div>
  </div>

  <!-- 暂停菜单 -->
  <div id="pause-menu">
    <div class="pause-box">
      <h2>游戏暂停</h2>
      <button id="pause-continue" class="mc-btn">继续游戏</button>
      <button id="pause-help-btn" class="mc-btn">操作说明</button>
      <div id="pause-help"></div>
    </div>
  </div>

  <!-- F3 调试 -->
  <div id="debug"></div>

  <!-- 水下滤镜 -->
  <div id="underwater-overlay"></div>

  <!-- 标题栏 -->
  <div id="title-bar">网页版 Minecraft — Wovra 还原</div>

  <!-- 加载屏 -->
  <div id="loading">
    <div id="loading-title">MINECRAFT</div>
    <div id="loading-sub">网页版 Minecraft — Wovra 还原</div>
    <div id="loading-bar-outer">
      <div id="loading-bar-inner"></div>
    </div>
    <div id="loading-tip">正在生成世界…</div>
  </div>

  <!-- 加载顺序（契约固定，不得改动）：
       three.js CDN → atlas.js → blocks.js → shaders.js → mesher.js → render.js
       → world.js → player.js → ui.js → main.js -->
  <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
  <script src="js/atlas.js"></script>
  <script src="js/blocks.js"></script>
  <script src="js/shaders.js"></script>
  <script src="js/mesher.js"></script>
  <script src="js/render.js"></script>
  <script src="js/world.js"></script>
  <script src="js/player.js"></script>
  <script src="js/ui.js"></script>
  <script src="js/main.js"></script>
</body>
</html>
