{"content":"// test/mesher.smoke.js — ST-B mesher 冒烟测试（Node 直接运行：node test/mesher.smoke.js）
// 用 mock world / mock THREE / mock MC_BLOCKS 验证：
//   1) 面剔除：全石头区块只产生顶面 256 quads
//   2) 贴图槽位：grass 的 py 用 grass_top / ny 用 dirt / 侧面用 grass_side
//   3) AO：单邻块遮挡 → 0.85，且触发对角翻转分支
//   4) 水面：顶面压低到 0.875、进 translucent 队列
//   5) 十字植物：2 个面片进 cutout 队列
//   6) 索引合法、UV 在 [0,1]、boundingSphere 已计算
'use strict';
global.window = global; // mesher 顶层读 window.MC_WORLD / window.MC_ATLAS

// ---- mock THREE（mesher 只用这几个 API） ----
var BufferGeometry = function () { this.attributes = {}; };
BufferGeometry.prototype.setAttribute = function (name, attr) { this.attributes[name] = attr; };
BufferGeometry.prototype.setIndex = function (idx) { this.index = idx; };
BufferGeometry.prototype.computeBoundingSphere = function () {
  var p = this.attributes.position.array, i;
  var min = [Infinity, Infinity, Infinity], max = [-Infinity, -Infinity, -Infinity];
  for (i = 0; i < p.length; i += 3) {
    for (var k = 0; k < 3; k++) {
      if (p[i + k] < min[k]) min[k] = p[i + k];
      if (p[i + k] > max[k]) max[k] = p[i + k];
    }
  }
  var cx = (min[0] + max[0]) / 2, cy = (min[1] + max[1]) / 2, cz = (min[2] + max[2]) / 2;
  var r = 0;
  for (i = 0; i < p.length; i += 3) {
    var dx = p[i] - cx, dy = p[i + 1] - cy, dz = p[i + 2] - cz;
    var d = Math.sqrt(dx * dx + dy * dy + dz * dz);
    if (d > r) r = d;
  }
  this.boundingSphere = { center: [cx, cy, cz], radius: r };
};
global.THREE = {
  BufferGeometry: BufferGeometry,
  Float32BufferAttribute: function (arr, size) { this.array = arr; this.itemSize = size; }
};

// ---- mock 方块表（结构同契约） ----
global.MC_BLOCKS = [null,
  { name: '石头', tex: ['stone'], solid: true, opaque: true, cross: false, translucent: false, cutout: false, light: 0 }, // 1
  { name: '草方块', tex: ['grass_top', 'dirt', 'grass_side'], solid: true, opaque: true, cross: false, translucent: false, cutout: false, light: 0 }, // 2
  { name: '水', tex: ['water'], solid: false, opaque: false, cross: false, translucent: true, cutout: false, light: 0 }, // 11
  { name: '草丛', tex: ['tall_grass'], solid: false, opaque: false, cross: true, translucent: false, cutout: false, light: 0 } // 25
];
global.MC_ATLAS = { T: { stone: 5, grass_top: 0, dirt: 1, grass_side: 2, water: 7, tall_grass: 9 } };

// ---- mock world：地表 y=41 以下全石头，之上空气；另放草块/水/植物 ----
var overrides = {
  '10,60,10': 2,   // 悬空草块：六面全暴露（测贴图槽位 + AO）
  '11,61,11': 1,   // 草块顶面 +x+z 角邻块 → AO 1 档
  '5,40,5': 11,    // 水洼（埋在地表下，只露顶面）
  '7,41,7': 25     // 草丛
};
var mockWorld = {
  getBlock: function (x, y, z) {
    if (y < 0 || y >= 96) return 0;
    var o = overrides[x + ',' + y + ',' + z];
    if (o !== undefined) return o;
    return y < 41 ? 1 : 0;
  }
};

require('../js/mesher.js');
var geoms = global.MC_MESHER.buildChunk(mockWorld, 0, 0);

function assert(cond, msg) { if (!cond) { console.error('FAIL: ' + msg); process.exit(1); } }
function near(a, b, eps, msg) { assert(Math.abs(a - b) <= (eps || 1e-4), msg + ' (got ' + a + ', want ' + b + ')'); }

// 1) opaque：只有 16×16 顶面（y=40 层的石头/水不露侧）+ 悬空草块 6 面 → 262 quads
var op = geoms.opaque;
assert(op, 'opaque 几何应存在');
var vCount = op.attributes.position.array.length / 3;
near(vCount, 262 * 4, 0.1, 'opaque 顶点数 = 262 quads × 4');
// 悬空草块的 6 个面按面序 px,nx,py,ny,pz,nz → 顶点 0..23
var P = op.attributes.position.array;
// px 面（顶点 0..3）应全部 x=11
for (var i = 0; i < 4; i++) near(P[i * 3], 11, 1e-6, '草块 px 面 x 坐标');
// py 面（顶点 8..11）应全部 y=61
for (i = 8; i < 12; i++) near(P[i * 3 + 1], 61, 1e-6, '草块 py 面 y 坐标');

// 2) 贴图槽位：py 用 grass_top(tile0: u≤1/16)，ny 用 dirt(tile1: u∈[1/16,2/16])，pz 用 grass_side(tile2)
var UV = op.attributes.uv.array;
function uvRange(start, count) {
  var mn = Infinity, mx = -Infinity;
  for (var j = start; j < start + count; j++) { if (UV[j] < mn) mn = UV[j]; if (UV[j] > mx) mx = UV[j]; }
  return [mn, mx];
}
var pyU = uvRange(16, 8);   // 顶点 8..11 的 u
assert(pyU[1] <= 1 / 16 + 1e-6, 'py 面 u 应在 tile0 列（grass_top）: ' + pyU);
var nyU = uvRange(24, 8);   // 顶点 12..15
assert(nyU[0] >= 1 / 16 - 1e-6 && nyU[1] <= 2 / 16 + 1e-6, 'ny 面 u 应在 tile1 列（dirt）: ' + nyU);
var pzU = uvRange(32, 8);   // 顶点 16..19
assert(pzU[0] >= 2 / 16 - 1e-6 && pzU[1] <= 3 / 16 + 1e-6, 'pz 面 u 应在 tile2 列（grass_side）: ' + pzU);
// 侧面 v 顶应≈1（绿边朝上）：pz 面四个顶点里 v 的最大值
var pzV = uvRange(33, 8);
near(pzV[1], 1 - 1 / 256, 1e-3, '侧面 vTop ≈ 1（贴图顶部朝上）');

// 3) AO：草块顶面顶点 (11,61,11) = 顶点 9，aLight.x 应为 1×1×0.85
var LIT = op.attributes.aLight.array;
near(LIT[9 * 2], 0.85, 1e-6, '顶点 AO 1 档 = 0.85');
near(LIT[8 * 2], 1.0, 1e-6, '其余顶点天光×shade = 1.0');
// 且顶面触发了对角翻转分支：索引中应出现 (b,b+1,b+3) 形态 → py quad 索引 8,9,11,8,11,10
var IDX = op.index;
assert(IDX[24] === 8 && IDX[25] === 9 && IDX[26] === 11 && IDX[27] === 8 && IDX[28] === 11 && IDX[29] === 10,
  'AO 翻转分支的三角形绕序应为 8,9,11 / 8,11,10');

// 4) 水：translucent 只有 1 个顶面 quad，顶点 y = 40.875 / 40
var wt = geoms.translucent;
assert(wt, 'translucent 几何应存在');
var WP = wt.attributes.position.array;
near(WP.length / 3, 4, 0.1, '水面只有 1 个顶面 quad');
for (i = 0; i < 4; i++) {
  var wy = WP[i * 3 + 1];
  assert(Math.abs(wy - 40.875) < 1e-6 || Math.abs(wy - 40) < 1e-6, '水面顶点 y 应为 40 / 40.875: ' + wy);
}
var wl = wt.attributes.aLight.array;
near(wl[0], 1.0, 1e-6, '露天水面天光 1.0');

// 5) 十字植物：cutout 恰好 2 quads（8 顶点）
var ct = geoms.cutout;
assert(ct, 'cutout 几何应存在');
near(ct.attributes.position.array.length / 3, 8, 0.1, '十字植物 = 2 quads');
var CP = ct.attributes.position.array;
// 两个对角面片端点应落在 (7.146,7.854) 内收对角上
near(CP[0] - 7, 0.146, 1e-6, '植物对角内收 x');

// 6) 通用：索引合法、UV∈[0,1]、boundingSphere
[geoms.opaque, geoms.cutout, geoms.translucent].forEach(function (g, gi) {
  if (!g) return;
  var n = g.attributes.position.array.length / 3;
  for (var j = 0; j < g.index.length; j++) assert(g.index[j] >= 0 && g.index[j] < n, '队列' + gi + ' 索引越界');
  for (j = 0; j < g.attributes.uv.array.length; j++) {
    assert(g.attributes.uv.array[j] >= -1e-6 && g.attributes.uv.array[j] <= 1 + 1e-6, '队列' + gi + ' UV 越界');
  }
  assert(g.boundingSphere && g.boundingSphere.radius > 0, '队列' + gi + ' boundingSphere 已计算');
});

console.log('mesher.smoke: 全部断言通过 ✓');
console.log('  opaque quads=262, water top face @0.875, cross=2 quads, AO flip 分支已验证');
